import { useEffect, useState } from "react";
import { getVersion } from "@tauri-apps/api/app";
import { useAppStore } from "@/store";
import { readGithubCache, describeCacheAge } from "@/shared/lib/github/githubState";
import { livePaneIds } from "@/app/console/lib/livePanes";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

interface StatusBarProps {
  extra?: React.ReactNode;
}
export function StatusBar({ extra }: StatusBarProps) {
  // Per-field selectors, not a bare whole-store read (#3612) — the StatusBar is always mounted, so a
  // whole-store subscription would re-render it on every unrelated store write.
  const claudeApiKey = useAppStore((s) => s.claudeApiKey);
  const githubConnected = useAppStore((s) => s.githubConnected);
  // WHEN that was last checked, and whether the cache has loaded at all
  // (`frontend-state-7-the-github-cluster-is-an-honest-cache`).
  const githubCheckedAt = useAppStore((s) => s.githubCheckedAt);
  const hasHydrated = useAppStore((s) => s.hasHydrated);
  // WHAT HAS BEEN STARTED — the launch generation `TerminalHost` holds — and the three maps that take a pane
  // OUT of the live set. Never the console tabs: no tab lists a project pane any more
  // (`project-fleet-panes-live-only-in-glance`).
  const launchGen = useAppStore((s) => s.paneLaunchGen);
  const endedPanes = useAppStore((s) => s.endedPanes);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const dormantPanes = useAppStore((s) => s.dormantPanes);

  // The real app version (from tauri.conf.json); drops the old hardcoded
  // "vX · rust Y" string (#215). Empty in a non-Tauri/web context.
  const [appVersion, setAppVersion] = useState("");
  useEffect(() => {
    getVersion().then(setAppVersion).catch(() => setAppVersion(""));
  }, []);

  const claudeOk  = Boolean(claudeApiKey);
  // "synced" was a claim about CURRENCY that nothing supported. It rendered off a boolean written once
  // by `finishConnect`, so a token verified seconds ago and one verified days ago read identically — and
  // a status bar exists to say what is true NOW. Three answers, never collapsed: verified inside the
  // window, verified a stated while ago, or connected with nothing having checked since.
  const githubCheck = readGithubCache({ hydrated: hasHydrated, value: githubConnected, fetchedAt: githubCheckedAt });
  const githubLabel = !githubConnected
    ? "not connected"
    : githubCheck?.status === "fresh"
      ? "connected"
      : githubCheck?.status === "stale"
        ? `connected · checked ${describeCacheAge(githubCheck.ageMs ?? 0)}`
        : "connected · not verified";
  // SESSIONS, NOT GRID CELLS. It is the same rule Glance's "End N sessions" reads, so the two cannot
  // disagree about what is running (`@/app/console/lib/livePanes`).
  const live = livePaneIds(launchGen, { endedPanes, disabledPanes, dormantPanes }).size;

  return (
    <Box className="statusbar">
      <Box className="s">
        <i className={claudeOk ? "" : "off"} />
        claude · {claudeOk ? "connected" : "no key"}
      </Box>
      <Box className="s">
        <i className={githubConnected ? "" : "off"} />
        github · {githubLabel}
      </Box>
      <Box className="spacer" />
      {extra}
      <Box className="s" style={{ color: "var(--fg-dim)" }} title={`${live} live project session${live === 1 ? "" : "s"}`}>
        {live} {live === 1 ? "session" : "sessions"}
      </Box>
      {appVersion && <Text as="div">v{appVersion}</Text>}
    </Box>
  );
}
